#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdio>

static inline float mx2(float a,float b){ return (a<b)?b:a; }
static inline float mn2(float a,float b){ return (b<a)?b:a; }

// branch: 0 = max==min, 1 = r&&g>=b, 2 = r&&g<b, 3 = g, 4 = b
static int branch_of(float r,float g,float b,float mxv,float mnv){
  if (mxv==mnv) return 0;
  if (mxv==r && g>=b) return 1;
  if (mxv==r) return 2;
  if (mxv==g) return 3;
  return 4;
}

// per-branch numerator operands and offsets
struct BInfo { float na, nb; float offdeg; float offsixth; };
static BInfo binfo(int br, float r,float g,float b){
  switch(br){
    case 1: return {g,b,0.0f,0.0f};
    case 2: return {g,b,360.0f,6.0f};
    case 3: return {b,r,120.0f,2.0f};
    default:return {r,g,240.0f,4.0f};
  }
}

// Each style returns a double which is what would be printed (already
// truncated to float where the variant stores to a float field).
static double hue_style(int st, float r, float g, float b){
  float mxv = mx2(mx2(r,g),b);
  float mnv = mn2(mn2(r,g),b);
  float delta = mxv - mnv;
  int br = branch_of(r,g,b,mxv,mnv);
  if (br==0) return 0.0;
  BInfo bi = binfo(br,r,g,b);
  float na=bi.na, nb=bi.nb, offf=bi.offdeg, off6f=bi.offsixth;
  double offd = (double)bi.offdeg, off6d = (double)bi.offsixth;
  switch(st){
  case 0: { // A  float, multiply-first, float offset  -> float
      float d = na-nb; float h = (60.0f*d)/delta; h = h + offf; return (double)h; }
  case 1: { // B  float, divide-first, float offset -> float
      float d = na-nb; float h = 60.0f*(d/delta); h = h + offf; return (double)h; }
  case 2: { // H  float factored: 60*(d/delta + off6)
      float d = na-nb; float h = 60.0f*((d/delta) + off6f); return (double)h; }
  case 3: { // H2 float factored other order: (off6 + d/delta)*60
      float d = na-nb; float h = (off6f + (d/delta))*60.0f; return (double)h; }
  case 4: { // C double all (exact sub), mul-first, double offset -> store float
      double h = 60.0*((double)na-(double)nb)/(double)delta + offd; return (double)(float)h; }
  case 5: { // D double all, mul-first -> store double
      double h = 60.0*((double)na-(double)nb)/(double)delta + offd; return h; }
  case 6: { // E double all, div-first -> store float
      double h = 60.0*(((double)na-(double)nb)/(double)delta) + offd; return (double)(float)h; }
  case 7: { // F double all, div-first -> store double
      double h = 60.0*(((double)na-(double)nb)/(double)delta) + offd; return h; }
  case 8: { // I double factored -> store float
      double h = 60.0*((((double)na-(double)nb)/(double)delta) + off6d); return (double)(float)h; }
  case 9: { // J double factored -> store double
      double h = 60.0*((((double)na-(double)nb)/(double)delta) + off6d); return h; }
  case 10:{ // K float sub, double mul/div/off -> store float
      float d = na-nb; double h = 60.0*(double)d/(double)delta + offd; return (double)(float)h; }
  case 11:{ // L float sub, double mul/div/off -> store double
      float d = na-nb; double h = 60.0*(double)d/(double)delta + offd; return h; }
  case 12:{ // N float mul/div, double offset add -> store double
      float d = na-nb; float h0 = (60.0f*d)/delta; double h = (double)h0 + offd; return h; }
  case 13:{ // O float divide-first, double offset add -> store double
      float d = na-nb; float h0 = 60.0f*(d/delta); double h = (double)h0 + offd; return h; }
  case 14:{ // P  "if (h<0) h+=360" normalisation, float mul-first
      float d, h;
      if (mxv==r) { d = g-b; h = (60.0f*d)/delta; if (h<0.0f) h += 360.0f; }
      else if (mxv==g) { d=b-r; h = (60.0f*d)/delta + 120.0f; }
      else { d=r-g; h=(60.0f*d)/delta + 240.0f; }
      return (double)h; }
  case 15:{ // Q float, mul-first but numerator subtraction done as -(nb-na)
      float d = -(nb-na); float h = (60.0f*d)/delta; h = h + offf; return (double)h; }
  case 16:{ // R float, offset applied first: 60.0f*d/delta where offset added before divide
      float d = na-nb; float h = (60.0f*d + offf*delta)/delta; return (double)h; }
  case 17:{ // S double sub only in numerator, float 60 mult: (60.0f*(float)((double)na-(double)nb))/delta
      float d = (float)((double)na-(double)nb); float h=(60.0f*d)/delta; h=h+offf; return (double)h; }
  }
  return 0.0;
}
