static const char* SNAME[NSTYLE] = {
 "A_f_mul","B_f_div","H_f_fact","H2_f_fact2","C_d_mul_sf","D_d_mul_sd","E_d_div_sf","F_d_div_sd",
 "I_d_fact_sf","J_d_fact_sd","K_fsub_d_sf","L_fsub_d_sd","N_f_doff_sd","O_fdiv_doff_sd",
 "P_norm360","Q_negsub","R_offbefore","S_dsub_fmul"};

int main(int argc,char**argv){
